actions.schema:
{
 "openapi": "3.0.3",
 "info": {
  "title": "StudioBook API",
  "version": "1"
 },
 "servers": [
  {
   "url": "https://{tenant}.studiobook.example/api",
   "variables": {
    "tenant": {
     "default": "app"
    }
   }
  }
 ],
 "paths": {
  "/classes": {
   "get": {
    "operationId": "list-classes",
    "summary": "List upcoming classes",
    "parameters": [
     {
      "$ref": "#/components/parameters/From"
     },
     {
      "name": "teacher",
      "in": "query",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "ok"
     }
    }
   }
  },
  "/bookings": {
   "get": {
    "operationId": "listMyBookings",
    "summary": "List the signed-in member's bookings",
    "responses": {
     "200": {
      "description": "ok"
     }
    }
   },
   "post": {
    "operationId": "createBooking",
    "summary": "Book a place in a class",
    "x-openai-isConsequential": true,
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "required": [
         "class_id"
        ],
        "properties": {
         "class_id": {
          "type": "string"
         },
         "guests": {
          "type": "integer",
          "minimum": 0,
          "maximum": 2,
          "default": 0
         },
         "note": {
          "type": "string",
          "nullable": true
         }
        }
       }
      }
     }
    },
    "responses": {
     "201": {
      "description": "created"
     }
    }
   }
  },
  "/bookings/{booking_id}": {
   "parameters": [
    {
     "name": "booking_id",
     "in": "path",
     "required": true,
     "schema": {
      "type": "string"
     }
    }
   ],
   "patch": {
    "operationId": "updateBooking",
    "summary": "Change the guest count or note on a booking",
    "requestBody": {
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "guests": {
          "type": "integer"
         },
         "note": {
          "type": "string"
         }
        }
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "ok"
     }
    }
   },
   "delete": {
    "operationId": "cancelBooking",
    "summary": "Cancel a booking",
    "x-openai-isConsequential": true,
    "responses": {
     "204": {
      "description": "cancelled"
     }
    }
   }
  },
  "/members/me/waiver": {
   "post": {
    "summary": "Upload a signed waiver",
    "requestBody": {
     "content": {
      "multipart/form-data": {
       "schema": {
        "type": "object",
        "properties": {
         "file": {
          "type": "string",
          "format": "binary"
         }
        }
       }
      }
     }
    },
    "responses": {
     "201": {
      "description": "stored"
     }
    }
   }
  }
 },
 "components": {
  "parameters": {
   "From": {
    "name": "from",
    "in": "query",
    "description": "First day to list, YYYY-MM-DD",
    "schema": {
     "type": "string",
     "format": "date"
    }
   }
  },
  "securitySchemes": {
   "oauth": {
    "type": "oauth2",
    "flows": {
     "authorizationCode": {
      "authorizationUrl": "https://app.studiobook.example/oauth/authorize",
      "tokenUrl": "https://app.studiobook.example/oauth/token",
      "scopes": {
       "bookings:read": "Read bookings",
       "bookings:write": "Create and cancel bookings"
      }
     }
    }
   }
  }
 }
}
